pragma solidity ^0.8.33;

/// @title IMetricOmmPoolImmutables
/// @notice Interface for reading pool immutable parameters in a single call
interface IMetricOmmPoolImmutables {
  /// @notice Returns all immutable parameters of the pool
  /// @return factory The factory address that created this pool
  /// @return priceProvider The price provider/oracle address
  /// @return token0 The first token of the pool
  /// @return token1 The second token of the pool
  /// @return initialToken0PerDistUnitPerShareE18 Initial token0 density per liquidity unit (in scaled units)
  /// @return initialToken1PerDistUnitPerShareE18 Initial token1 density per liquidity unit (in scaled units)
  /// @return minimalMintableLiquidity Minimum liquidity that can be minted
  /// @return reportSwapToPriceProvider Whether post-swap reporting to price provider is enabled
  /// @return maxDriftE8 Maximum drift value in 1/1e8 units
  /// @return maxDriftDecayPerSecondE8 Drift decay rate per second in 1/1e8 units
  /// @return lowestBin The lowest bin index
  /// @return highestBin The highest bin index
  /// @return token0ScaleMultiplier Multiplier to scale token0 external amounts to internal (10^(internalDecimals - token0.decimals()))
  /// @return token1ScaleMultiplier Multiplier to scale token1 external amounts to internal (10^(internalDecimals - token1.decimals()))
  function getImmutables()
    external
    view
    returns (
      address factory,
      address priceProvider,
      address token0,
      address token1,
      uint104 initialToken0PerDistUnitPerShareE18,
      uint104 initialToken1PerDistUnitPerShareE18,
      uint104 minimalMintableLiquidity,
      bool reportSwapToPriceProvider,
      uint256 maxDriftE8,
      uint256 maxDriftDecayPerSecondE8,
      int16 lowestBin,
      int16 highestBin,
      uint256 token0ScaleMultiplier,
      uint256 token1ScaleMultiplier
    );
}

