// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.33;

import {IExtsload} from "../interfaces/IExtsload.sol";

/// @title PoolStateLibrary
/// @notice Read MetricOmmPool storage via EXTSLOAD (no native view getters on the pool)
/// @dev Constants and packing must match MetricOmmPool storage layout exactly.
///
/// Storage Layout:
/// Slot 0: curBinIdx(int16,0) | curPosInBin(uint104,2) | curBinDistFromProvidedPriceE6(int32,14) |
///         driftE8(int32,18) | performanceFeeE6(uint24,22) | locked(uint8,25) | _slot0Unused(bytes5,26)
/// Slot 1: totalScaledToken0InBins(uint128,0) | totalScaledToken1InBins(uint128,16)
/// Slot 2: _binsStates mapping(int16 => BinState)
/// Slot 3: _binsTotalShares mapping(int16 => uint104)
/// Slot 4: _positionBinShares mapping(bytes32 => uint104)
/// Slot 5: admin(address,0) | protocolFeeE6(uint24,20) | adminFeeE6(uint24,23) | lastTradeTimestamp(uint48,26)
/// Slot 6: adminFeeDestination(address,0)
/// Slot 7: PRICE_PROVIDER(address,0)
library PoolStateLibrary {
  // ========= Storage Slot Constants =========
  uint256 internal constant SLOT_0 = 0;
  uint256 internal constant SLOT_1 = 1;
  uint256 internal constant BINS_STATES_SLOT = 2;
  uint256 internal constant BINS_TOTAL_SHARES_SLOT = 3;
  uint256 internal constant POSITION_BIN_SHARES_SLOT = 4;
  uint256 internal constant ADMIN_AND_FEES_SLOT = 5;
  uint256 internal constant ADMIN_FEE_DEST_SLOT = 6;
  uint256 internal constant PRICE_PROVIDER_SLOT = 7;

  // ========= Slot0 Readers =========

  /// @notice Get current bin index
  function getCurBinIdx(address pool) internal view returns (int16) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    return int16(uint16(uint256(data)));
  }

  /// @notice Get current position in bin
  function getCurPosInBin(address pool) internal view returns (uint104) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    return uint104(uint256(data) >> 16);
  }

  /// @notice Get current bin distance in units
  function getCurBinDistInUnits(address pool) internal view returns (int32) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    return int32(uint32(uint256(data) >> 120));
  }

  /// @notice Get drift value
  function getDriftE8(address pool) internal view returns (int32) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    return int32(uint32(uint256(data) >> 152));
  }

  /// @notice Get performance fee
  function getPerformanceFeeE6(address pool) internal view returns (uint24) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    return uint24(uint256(data) >> 184);
  }

  /// @notice Get all slot0 values in a single call
  function getSlot0(address pool)
    internal
    view
    returns (
      int16 curBinIdx,
      uint104 curPosInBin,
      int32 curBinDistFromProvidedPriceE6,
      int32 driftE8,
      uint24 performanceFeeE6
    )
  {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_0));
    uint256 packed = uint256(data);
    curBinIdx = int16(uint16(packed));
    curPosInBin = uint104(packed >> 16);
    curBinDistFromProvidedPriceE6 = int32(uint32(packed >> 120));
    driftE8 = int32(uint32(packed >> 152));
    performanceFeeE6 = uint24(packed >> 184);
  }

  // ========= Slot1 Readers =========

  /// @notice Get total scaled token0 balance across all bins
  function getTotalScaledToken0InBins(address pool) internal view returns (uint128) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_1));
    return uint128(uint256(data));
  }

  /// @notice Get total scaled token1 balance across all bins
  function getTotalScaledToken1InBins(address pool) internal view returns (uint128) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_1));
    return uint128(uint256(data) >> 128);
  }

  /// @notice Get all slot1 values in a single call
  function getSlot1(address pool) internal view returns (uint128 totalScaledToken0InBins, uint128 totalScaledToken1InBins) {
    bytes32 data = IExtsload(pool).extsload(bytes32(SLOT_1));
    uint256 packed = uint256(data);
    totalScaledToken0InBins = uint128(packed);
    totalScaledToken1InBins = uint128(packed >> 128);
  }

  /// @notice Get last trade timestamp (now packed in admin slot)
  function getLastTradeTimestamp(address pool) internal view returns (uint48) {
    bytes32 data = IExtsload(pool).extsload(bytes32(ADMIN_AND_FEES_SLOT));
    return uint48(uint256(data) >> 208);
  }

  // ========= Bin State Readers =========

  /// @notice Calculate the storage slot for a bin state
  /// @dev For mapping(int16 => BinState), slot = keccak256(abi.encode(key, baseSlot))
  function _getBinStateSlot(int16 binIdx) private pure returns (bytes32) {
    return keccak256(abi.encode(binIdx, BINS_STATES_SLOT));
  }

  /// @notice Calculate the storage slot for bin total shares
  function _getBinTotalSharesSlot(int16 binIdx) private pure returns (bytes32) {
    return keccak256(abi.encode(binIdx, BINS_TOTAL_SHARES_SLOT));
  }

  /// @notice Get bin state (balances and configuration)
  /// @dev BinState: token0Balance(uint104) | token1Balance(uint104) | lengthE6(uint24) | addFeeBuyE6(uint16) | addFeeSellE6(uint16)
  function getBinState(address pool, int16 binIdx)
    internal
    view
    returns (uint104 token0Balance, uint104 token1Balance, uint16 lengthE6, uint16 addFeeBuyE6, uint16 addFeeSellE6)
  {
    bytes32 slot = _getBinStateSlot(binIdx);
    bytes32 data = IExtsload(pool).extsload(slot);
    uint256 packed = uint256(data);
    token0Balance = uint104(packed);
    token1Balance = uint104(packed >> 104);
    lengthE6 = uint16(packed >> 208);
    addFeeBuyE6 = uint16(packed >> 224);
    addFeeSellE6 = uint16(packed >> 240);
  }

  /// @notice Get bin total shares
  function getBinTotalShares(address pool, int16 binIdx) internal view returns (uint104) {
    bytes32 slot = _getBinTotalSharesSlot(binIdx);
    bytes32 data = IExtsload(pool).extsload(slot);
    return uint104(uint256(data));
  }

  /// @notice Get bin states for multiple bins in batch
  function getBinStates(address pool, int16[] calldata binIdxs)
    internal
    view
    returns (
      uint104[] memory token0Balances,
      uint104[] memory token1Balances,
      uint16[] memory lengthsInUnits,
      uint16[] memory addFeeBuysE6,
      uint16[] memory addFeeSellsE6,
      uint104[] memory totalShares
    )
  {
    uint256 length = binIdxs.length;
    bytes32[] memory slots = new bytes32[](length * 2);

    for (uint256 i = 0; i < length; i++) {
      slots[i] = _getBinStateSlot(binIdxs[i]);
      slots[length + i] = _getBinTotalSharesSlot(binIdxs[i]);
    }

    bytes32[] memory results = IExtsload(pool).extsload(slots);

    token0Balances = new uint104[](length);
    token1Balances = new uint104[](length);
    lengthsInUnits = new uint16[](length);
    addFeeBuysE6 = new uint16[](length);
    addFeeSellsE6 = new uint16[](length);
    totalShares = new uint104[](length);

    for (uint256 i = 0; i < length; i++) {
      uint256 packed = uint256(results[i]);
      token0Balances[i] = uint104(packed);
      token1Balances[i] = uint104(packed >> 104);
      lengthsInUnits[i] = uint16(packed >> 208);
      addFeeBuysE6[i] = uint16(packed >> 224);
      addFeeSellsE6[i] = uint16(packed >> 240);
      totalShares[i] = uint104(uint256(results[length + i]));
    }
  }

  // ========= Position Readers =========

  /// @notice Calculate the storage slot for position bin shares
  /// @dev positionBinKey layout: [address(160)] | [salt(72)] | [bin(24)] = 256 bits
  function _getPositionBinSharesSlot(bytes32 positionBinKey) private pure returns (bytes32) {
    return keccak256(abi.encode(positionBinKey, POSITION_BIN_SHARES_SLOT));
  }

  /// @notice Create a position bin key
  function toPositionBinKey(address owner, uint80 salt, int16 bin) internal pure returns (bytes32) {
    return bytes32((uint256(uint160(owner)) << 96) | (uint256(salt) << 16) | uint256(uint16(bin)));
  }

  /// @notice Get position bin shares
  function getPositionBinShares(address pool, address owner, uint80 salt, int16 bin) internal view returns (uint104) {
    bytes32 positionBinKey = toPositionBinKey(owner, salt, bin);
    bytes32 slot = _getPositionBinSharesSlot(positionBinKey);
    bytes32 data = IExtsload(pool).extsload(slot);
    return uint104(uint256(data));
  }

  /// @notice Get position bin shares by key
  function getPositionBinShares(address pool, bytes32 positionBinKey) internal view returns (uint104) {
    bytes32 slot = _getPositionBinSharesSlot(positionBinKey);
    bytes32 data = IExtsload(pool).extsload(slot);
    return uint104(uint256(data));
  }

  /// @notice Get position bin shares for multiple position-bin keys in a single call
  /// @param pool The pool address
  /// @param positionBinKeys Array of position bin keys (packed: owner|salt|bin)
  /// @return shares Array of shares for each position-bin key
  function getPositionBinSharesBatch(address pool, bytes32[] calldata positionBinKeys)
    internal
    view
    returns (uint104[] memory shares)
  {
    uint256 length = positionBinKeys.length;
    bytes32[] memory slots = new bytes32[](length);
    for (uint256 i = 0; i < length; i++) {
      slots[i] = _getPositionBinSharesSlot(positionBinKeys[i]);
    }
    bytes32[] memory results = IExtsload(pool).extsload(slots);
    shares = new uint104[](length);
    for (uint256 i = 0; i < length; i++) {
      shares[i] = uint104(uint256(results[i]));
    }
  }

  // ========= Admin / Fees =========

  /// @notice Get admin address
  function getAdmin(address pool) internal view returns (address) {
    bytes32 data = IExtsload(pool).extsload(bytes32(ADMIN_AND_FEES_SLOT));
    return address(uint160(uint256(data)));
  }

  /// @notice Get protocol fee
  function getProtocolFeeE6(address pool) internal view returns (uint24) {
    bytes32 data = IExtsload(pool).extsload(bytes32(ADMIN_AND_FEES_SLOT));
    return uint24(uint256(data) >> 160);
  }

  /// @notice Get admin fee
  function getAdminFeeE6(address pool) internal view returns (uint24) {
    bytes32 data = IExtsload(pool).extsload(bytes32(ADMIN_AND_FEES_SLOT));
    return uint24(uint256(data) >> 184);
  }

  /// @notice Get fee configuration
  function getFeeConfig(address pool)
    internal
    view
    returns (address admin, uint24 protocolFeeE6, uint24 adminFeeE6, address adminFeeDestination)
  {
    bytes32 data6 = IExtsload(pool).extsload(bytes32(ADMIN_AND_FEES_SLOT));
    bytes32 data7 = IExtsload(pool).extsload(bytes32(ADMIN_FEE_DEST_SLOT));
    uint256 packed = uint256(data6);
    admin = address(uint160(packed));
    protocolFeeE6 = uint24(packed >> 160);
    adminFeeE6 = uint24(packed >> 184);
    adminFeeDestination = address(uint160(uint256(data7)));
  }

  /// @notice Get admin fee destination
  function getAdminFeeDestination(address pool) internal view returns (address) {
    bytes32 data = IExtsload(pool).extsload(bytes32(ADMIN_FEE_DEST_SLOT));
    return address(uint160(uint256(data)));
  }

  /// @notice Get price provider address
  function getPriceProvider(address pool) internal view returns (address) {
    bytes32 data = IExtsload(pool).extsload(bytes32(PRICE_PROVIDER_SLOT));
    return address(uint160(uint256(data)));
  }
}

