// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.33;

import "./libraries/PoolStateLibrary.sol";
import "./interfaces/IMetricOmmPool/IMetricOmmPoolImmutables.sol";

/// @title MetricOmmPoolStateView
/// @notice Off-chain friendly view helpers reading pool state via EXTSLOAD
/// @dev This contract provides convenient wrappers around PoolStateLibrary for external use.
///      Amounts are returned in EXTERNAL (native token decimal) units by unscaling internal storage values.
contract MetricOmmPoolStateView {
  using PoolStateLibrary for address;

  /// @notice Get scale multipliers for a pool
  function getScaleMultipliers(address pool)
    public
    view
    returns (uint256 token0ScaleMultiplier, uint256 token1ScaleMultiplier)
  {
    (,,,,,,,,,,,, token0ScaleMultiplier, token1ScaleMultiplier) = IMetricOmmPoolImmutables(pool).getImmutables();
  }

  /// @notice Get all slot0 values
  function slot0(address pool)
    external
    view
    returns (
      int16 _curBinIdx,
      uint104 _curPosInBin,
      int32 _curBinDistFromProvidedPrice,
      int32 _driftE8,
      uint24 _performanceFeeE6
    )
  {
    return PoolStateLibrary.getSlot0(pool);
  }

  /// @notice Get all slot1 values (bin totals in EXTERNAL units)
  function slot1(address pool) external view returns (uint128 _totalScaledToken0InBins, uint128 _totalScaledToken1InBins) {
    (uint256 scale0, uint256 scale1) = getScaleMultipliers(pool);
    (uint128 scaled0, uint128 scaled1) = PoolStateLibrary.getSlot1(pool);
    _totalScaledToken0InBins = uint128(uint256(scaled0) / scale0);
    _totalScaledToken1InBins = uint128(uint256(scaled1) / scale1);
  }

  /// @notice Get current bin index
  function curBinIdx(address pool) external view returns (int16) {
    return PoolStateLibrary.getCurBinIdx(pool);
  }

  /// @notice Get current position in bin
  function curPosInBin(address pool) external view returns (uint104) {
    return PoolStateLibrary.getCurPosInBin(pool);
  }

  /// @notice Get current bin distance in units
  function curBinDistFromProvidedPriceE6(address pool) external view returns (int32) {
    return PoolStateLibrary.getCurBinDistInUnits(pool);
  }

  /// @notice Get drift value
  function driftE8(address pool) external view returns (int32) {
    return PoolStateLibrary.getDriftE8(pool);
  }

  /// @notice Get performance fee
  function performanceFeeE6(address pool) external view returns (uint24) {
    return PoolStateLibrary.getPerformanceFeeE6(pool);
  }

  /// @notice Get total scaled token0 balance across all bins (in EXTERNAL units)
  function totalToken0InBins(address pool) external view returns (uint128) {
    (uint256 scale0,) = getScaleMultipliers(pool);
    return uint128(uint256(PoolStateLibrary.getTotalScaledToken0InBins(pool)) / scale0);
  }

  /// @notice Get total scaled token1 balance across all bins (in EXTERNAL units)
  function totalToken1InBins(address pool) external view returns (uint128) {
    (, uint256 scale1) = getScaleMultipliers(pool);
    return uint128(uint256(PoolStateLibrary.getTotalScaledToken1InBins(pool)) / scale1);
  }

  /// @notice Get last trade timestamp
  function lastTradeTimestamp(address pool) external view returns (uint48) {
    return PoolStateLibrary.getLastTradeTimestamp(pool);
  }

  /// @notice Get bin state (balances in EXTERNAL units)
  function binState(address pool, int16 binIdx)
    external
    view
    returns (uint104 token0Balance, uint104 token1Balance, uint16 lengthE6, uint16 addFeeBuyE6, uint16 addFeeSellE6)
  {
    (uint256 scale0, uint256 scale1) = getScaleMultipliers(pool);
    uint104 scaled0;
    uint104 scaled1;
    (scaled0, scaled1, lengthE6, addFeeBuyE6, addFeeSellE6) = PoolStateLibrary.getBinState(pool, binIdx);
    token0Balance = uint104(uint256(scaled0) / scale0);
    token1Balance = uint104(uint256(scaled1) / scale1);
  }

  /// @notice Get bin state in INTERNAL (scaled) units - for debugging/advanced use
  function binStateScaled(address pool, int16 binIdx)
    external
    view
    returns (
      uint104 token0BalanceScaled,
      uint104 token1BalanceScaled,
      uint16 lengthE6,
      uint16 addFeeBuyE6,
      uint16 addFeeSellE6
    )
  {
    return PoolStateLibrary.getBinState(pool, binIdx);
  }

  /// @notice Get bin total shares
  function binTotalShares(address pool, int16 binIdx) external view returns (uint104) {
    return PoolStateLibrary.getBinTotalShares(pool, binIdx);
  }

  /// @notice Get bin states for multiple bins (balances in EXTERNAL units)
  function binStates(address pool, int16[] calldata binIdxs)
    external
    view
    returns (
      uint104[] memory token0Balances,
      uint104[] memory token1Balances,
      uint16[] memory lengthsInUnits,
      uint16[] memory addFeeBuysE6,
      uint16[] memory addFeeSellsE6,
      uint104[] memory totalShares
    )
  {
    (uint256 scale0, uint256 scale1) = getScaleMultipliers(pool);

    uint104[] memory scaled0;
    uint104[] memory scaled1;
    (scaled0, scaled1, lengthsInUnits, addFeeBuysE6, addFeeSellsE6, totalShares) =
      PoolStateLibrary.getBinStates(pool, binIdxs);

    uint256 length = binIdxs.length;
    token0Balances = new uint104[](length);
    token1Balances = new uint104[](length);

    for (uint256 i = 0; i < length; i++) {
      token0Balances[i] = uint104(uint256(scaled0[i]) / scale0);
      token1Balances[i] = uint104(uint256(scaled1[i]) / scale1);
    }
  }

  /// @notice Get bin states in INTERNAL (scaled) units - for debugging/advanced use
  function binStatesScaled(address pool, int16[] calldata binIdxs)
    external
    view
    returns (
      uint104[] memory token0BalancesScaled,
      uint104[] memory token1BalancesScaled,
      uint16[] memory lengthsInUnits,
      uint16[] memory addFeeBuysE6,
      uint16[] memory addFeeSellsE6,
      uint104[] memory totalShares
    )
  {
    return PoolStateLibrary.getBinStates(pool, binIdxs);
  }

  /// @notice Get position bin shares
  function positionBinShares(address pool, address owner, uint80 salt, int16 bin) external view returns (uint104) {
    return PoolStateLibrary.getPositionBinShares(pool, owner, salt, bin);
  }

  /// @notice Get position bin shares by key
  function positionBinShares(address pool, bytes32 positionBinKey) external view returns (uint104) {
    return PoolStateLibrary.getPositionBinShares(pool, positionBinKey);
  }

  /// @notice Get position bin shares for multiple position-bin keys in a single call
  /// @param pool The pool address
  /// @param positionBinKeys Array of position bin keys (packed: owner|salt|bin)
  /// @return shares Array of shares for each position-bin key
  function positionBinSharesBatch(address pool, bytes32[] calldata positionBinKeys)
    external
    view
    returns (uint104[] memory shares)
  {
    return PoolStateLibrary.getPositionBinSharesBatch(pool, positionBinKeys);
  }

  /// @notice Get admin address
  function admin(address pool) external view returns (address) {
    return PoolStateLibrary.getAdmin(pool);
  }

  /// @notice Get protocol fee
  function protocolFeeE6(address pool) external view returns (uint24) {
    return PoolStateLibrary.getProtocolFeeE6(pool);
  }

  /// @notice Get admin fee
  function adminFeeE6(address pool) external view returns (uint24) {
    return PoolStateLibrary.getAdminFeeE6(pool);
  }

  /// @notice Get admin fee destination
  function adminFeeDestination(address pool) external view returns (address) {
    return PoolStateLibrary.getAdminFeeDestination(pool);
  }

  /// @notice Get full fee configuration
  function feeConfig(address pool)
    external
    view
    returns (address adminAddr, uint24 protocolFee, uint24 adminFee, address adminFeeDest)
  {
    return PoolStateLibrary.getFeeConfig(pool);
  }

  /// @notice Get price provider address
  function priceProvider(address pool) external view returns (address) {
    return PoolStateLibrary.getPriceProvider(pool);
  }
}
